from modele import C,E

C('Jouer avec les euros','Mesures','P2 ou P3',
 'Je forme une somme et je simule un achat.','Monnaie de jeu : 1 €, 2 €, 5 €, 10 €, 20 €, 50 €.',
 'Échange dix pièces de 1 € contre un billet de 10 €. Compare ensuite un billet de 5 € et trois pièces de 1 €.',
 ['Je compte la valeur des pièces et des billets.', 'Plus de pièces ne veut pas toujours dire plus d’argent.', 'La monnaie rendue complète ce que je paie pour retrouver ce que j’ai donné.'],
 'Un objet coûte 7 €. Je donne 10 €. On me rend 3 €, car 7 + 3 = 10.',('money',[5,2,1]),
 'Forme 12 € avec un billet de 10 € et des pièces de 1 €.', '10 € + 1 € + 1 € = 12 €.',[
 E('Quelle somme est représentée ?','10 € + 5 € + 2 € = 17 €.',('money',[10,5,2]),'10+5+2==17'),
 E('Dessine la monnaie pour faire 8 € avec 5 €, 2 € et 1 €.','5 € + 2 € + 1 € = 8 €.'),
 E('Qui a le plus : A a un billet de 10 € ; B a quatre pièces de 2 € ?','A a 10 €. B a 8 €. A a plus d’argent, même avec moins d’objets.'),
 E('Forme 24 € avec le moins d’objets parmi des billets de 10 € et des pièces de 2 €.','2 billets de 10 € et 2 pièces de 2 € : 4 objets.'),
 E('Un livre coûte 13 €. Tu donnes 20 €. Combien te rend-on ?','20 - 13 = 7 €. On rend 7 €.',None,'20-13==7'),
 E('Une boîte coûte 28 €. Tu as 35 €. Combien reste-t-il après l’achat ?','35 - 28 = 7 €. Il reste 7 €.',None,'35-28==7'),
 E('Un cahier coûte 4 € et un livre 9 €. Combien faut-il payer ?','4 + 9 = 13 €. Il faut payer 13 €.',None,'4+9==13'),
 E('Un jeu coûte 36 €. Tu as un billet de 20 € et un de 10 €. Combien manque-t-il ?','Tu as 30 €. Il manque 6 €.',None,'36-20-10==6'),
 E('Joue au magasin : choisis un prix de 1 à 20 €, paie avec 20 €, puis vérifie la monnaie reçue.','La monnaie rendue doit compléter le prix pour faire 20 €. Par exemple, pour 12 €, on rend 8 €.')],
 'Faire jouer tour à tour l’acheteur et le vendeur avec la monnaie de jeu.', 'Utiliser uniquement des montants entiers en euros et préciser les pièces disponibles.')

C('Comparer et mesurer des longueurs','Mesures','P2 puis toute l’année',
 'Je compare, je mesure et je trace en centimètres.','Règle graduée, bandes de papier et ficelle.',
 'Compare deux bandes en alignant une extrémité. Mesure ensuite la plus longue en plaçant le zéro de la règle au départ.',
 ['Pour comparer, j’aligne une extrémité des objets.', 'Pour mesurer, je place le zéro au début du segment.', 'Un mètre vaut 100 centimètres : 1 m = 100 cm.'],
 'Le segment va de 0 à 6 sur la règle : il mesure 6 cm.',('ruler',[0,6]),
 'Avec une vraie règle, trace un segment de 4 cm.', 'Le segment doit mesurer 4 cm. Vérifier les deux extrémités avec le zéro.',[
 E('Lis la longueur du segment sur la règle dessinée.','5 cm : le segment commence à 0 et finit à 5.',('ruler',[0,5])),
 E('Compare les bandes A, B et C. Range-les de la plus courte à la plus longue.','B ; A ; C. Elles mesurent 3, 5 et 7 unités de dessin.',('lengths',[5,3,7])),
 E('Avec ta règle, trace un segment de 7 cm.','Le segment mesure exactement 7 cm à l’impression à 100 % ou sur ta propre feuille.'),
 E('Le segment va de 2 à 8 sur cette règle. Quelle est sa longueur ?','8 - 2 = 6 cm. Il faut compter l’écart, pas lire seulement 8.',('ruler',[2,8]),'8-2==6'),
 E('Choisis l’unité : longueur d’un crayon, cm ou m ? Hauteur d’une porte, cm ou m ?','Crayon : cm. Porte : m, avec une hauteur voisine de 2 m.'),
 E('Complète : 1 m = … cm.','100 cm.'),
 E('Une bande mesure 12 cm. On coupe 4 cm. Quelle longueur reste-t-il ?','12 - 4 = 8 cm.',None,'12-4==8'),
 E('Un ruban rouge mesure 8 cm et un bleu 6 cm. Mis bout à bout, quelle longueur font-ils ?','8 + 6 = 14 cm.',None,'8+6==14'),
 E('Comment comparer la largeur de deux tables éloignées sans les déplacer ?','Reporter chaque largeur avec une ficelle ou une bande de papier, puis comparer les reports.')],
 'Revenir aux extrémités communes et au report d’un étalon sans espace.', 'Imprimer en taille réelle. Les segments de cette page sont à l’échelle ; contrôler le repère de 5 cm.')

C('Plus lourd, plus léger','Mesures','Manipuler dès P1, structurer en P3',
 'Je compare des masses en manipulant.','Une balance à plateaux ; trois boîtes opaques préparées par l’adulte.',
 'Soupèse deux boîtes de même forme mais de masses différentes. Vérifie ensuite avec une balance.',
 ['Une masse se compare avec les mains ou une balance.', 'Sur une balance à plateaux, le côté le plus bas porte la masse la plus grande.', 'Deux plateaux au même niveau indiquent des masses égales si la balance est réglée.'],
 'Le plateau A est plus bas que le plateau B : A est plus lourd que B.',('balance','left'),
 'Sur la balance de l’exemple, quelle boîte est la plus légère ?', 'B, puisque son plateau est plus haut.',[
 E('Quelle boîte est la plus lourde ?','B : le plateau de droite est plus bas.',('balance','right')),
 E('Les plateaux sont au même niveau. Que peux-tu dire des masses ?','Elles sont égales, si la balance est correctement réglée.',('balance','equal')),
 E('Une grosse boîte est vide. Une petite boîte contient des cailloux. Peux-tu savoir laquelle est la plus lourde en regardant ?','Non. Il faut les soupeser ou utiliser une balance.'),
 E('Manipule deux boîtes préparées par l’adulte. Annonce la plus lourde, puis vérifie.','Réponse selon les objets. La vérification doit être faite à la balance.'),
 E('A est plus lourd que B. B est plus lourd que C. Range de la plus légère à la plus lourde.','C ; B ; A.'),
 E('A et B ont la même masse. C est plus lourd que A. Compare C et B.','C est aussi plus lourd que B.'),
 E('Tu veux équilibrer une boîte avec des cubes identiques. Que peux-tu faire ?','Ajouter des cubes dans l’autre plateau jusqu’à ce que les deux plateaux soient au même niveau.'),
 E('Trie trois boîtes de même taille de la plus légère à la plus lourde. Explique comment vérifier.','Comparer les boîtes deux à deux avec la balance, puis contrôler l’ordre obtenu.'),
 E('Lina dit : « L’objet le plus haut est toujours le plus lourd. » Est-ce vrai ?','Non. La hauteur et la masse sont deux grandeurs différentes. Il faut comparer les masses.')],
 'Privilégier des objets de même apparence pour dissocier taille et masse.', 'Pas d’unité de masse à mémoriser ici ; les situations sont réellement manipulées.')

C('Lire les heures entières','Mesures','P3',
 'Je lis l’heure et je place les aiguilles.','Une horloge à aiguilles manipulables.',
 'Place la grande aiguille sur 12. Déplace la petite aiguille sur 8, puis sur 10.',
 ['La petite aiguille indique l’heure.', 'Pour une heure entière, la grande aiguille est sur 12.', 'Je relie l’heure à un moment de la journée.'],
 'Petite aiguille sur 8, grande aiguille sur 12 : il est 8 heures.',('clocks',[8]),
 'Place les aiguilles pour montrer 3 heures.', 'La petite aiguille est sur 3 ; la grande est sur 12.',[
 E('Lis l’heure sur chaque horloge.','4 heures ; 9 heures.',('clocks',[4,9])),
 E('Dessine les aiguilles pour 6 heures.','Petite aiguille sur 6 et grande sur 12.',('blankclocks',1)),
 E('Dessine les aiguilles pour 11 heures.','Petite aiguille sur 11 et grande sur 12.',('blankclocks',1)),
 E('À une heure entière, où se trouve la grande aiguille ?','Sur 12.'),
 E('Lis l’heure. Quel autre nom donne-t-on à 12 heures au milieu de la journée ?','12 heures, ou midi.',('clocks',[12])),
 E('Qu’est-ce qui peut correspondre à 8 heures du matin : aller à l’école ou dîner ?','Aller à l’école, selon l’organisation de la journée. Le contexte est précisé par « du matin ».'),
 E('Le matin, Lina se lève à 7 heures et entre en classe à 9 heures. Quel événement arrive en premier ?','Elle se lève à 7 heures, puis entre en classe à 9 heures.'),
 E('Place 2 heures sur ton horloge. Où sont les deux aiguilles ?','Petite sur 2 ; grande sur 12.'),
 E('Nino lit « 12 heures » parce que la grande aiguille est sur 12. La petite est sur 5. Corrige.','Il est 5 heures. Pour lire l’heure entière, on regarde la petite aiguille.')],
 'Utiliser deux aiguilles de longueurs nettement différentes, puis varier les cadrans.', 'Rester aux heures entières de 1 à 12 ; les demi-heures seront étudiées plus tard.')

C('Reconnaître les formes et tracer','Géométrie','Dès P1, puis approfondir',
 'Je nomme les formes et j’utilise la règle.','Formes en carton, règle et crayon.',
 'Trie des triangles et des carrés tournés dans plusieurs sens. Passe le doigt le long des côtés et compte les sommets.',
 ['Un triangle a 3 côtés et 3 sommets.', 'Un carré a 4 côtés de même longueur et 4 coins droits. Un rectangle a 4 coins droits.', 'La règle permet de tracer des traits droits et de vérifier un alignement.'],
 'Tourner un carré ne change pas sa forme : c’est toujours un carré.',('shapes','lesson'),
 'Montre un triangle et compte ses sommets.', 'Il a 3 sommets et 3 côtés.',[
 E('Nomme les formes A, B, C et D.','A : carré ; B : triangle ; C : disque ; D : rectangle.',('shapes','quiz')),
 E('Combien de côtés et de sommets a un triangle ? Et un carré ?','Triangle : 3 et 3. Carré : 4 et 4.'),
 E('Relie les points A et B avec une règle.','Le tracé doit passer par les deux points.',('points',[(0,0,'A'),(6,2,'B')])),
 E('Vérifie avec la règle : A, B et C sont-ils alignés ?','Oui : la règle peut passer par les trois points.',('points',[(0,0,'A'),(3,1,'B'),(6,2,'C')])),
 E('Vérifie avec la règle : A, B et C sont-ils alignés ?','Non : le point B est en dehors du trait passant par A et C.',('points',[(0,0,'A'),(3,2,'B'),(6,0,'C')])),
 E('Dessine un triangle avec ta règle. Marque ses sommets.','Trois segments fermant la figure ; trois sommets marqués.'),
 E('Une forme a 4 côtés égaux et 4 coins droits. Quelle forme est-ce ?','Un carré.'),
 E('Trace un trait droit qui passe par deux points de ton choix. Prolonge-le des deux côtés.','La règle reste placée sur les deux points pendant le tracé.'),
 E('Un enfant appelle un disque « une boule ». Explique la différence avec un objet.','Un disque est une forme plane, comme une découpe de papier. Une boule est un solide, comme une balle.')],
 'Faire manipuler les formes dans plusieurs orientations et utiliser des gabarits.', 'Ne pas définir un carré par sa seule orientation ; distinguer disque et boule.')

C('Construire sur un quadrillage','Géométrie','P4',
 'Je reproduis et je complète une figure.','Règle et papier quadrillé.',
 'Repère un sommet d’un modèle. Compte les carreaux le long de chaque côté et reproduis la figure à côté.',
 ['Je repère les sommets avant de tracer.', 'Je compte les carreaux, pas seulement les traits du quadrillage.', 'Pour ces carrés et rectangles, les côtés suivent les lignes du quadrillage.'],
 'Un rectangle de 4 carreaux sur 2 carreaux a deux grands côtés de 4 et deux petits de 2.',('gridshape',('rectangle',4,2)),
 'Trace un carré de 3 carreaux de côté sur ta feuille.', 'Les quatre côtés mesurent chacun 3 carreaux.',[
 E('Reproduis ce rectangle sur le quadrillage vide.','Rectangle de 4 carreaux sur 2 ; les sommets sont sur les croisements.',('copygrid',('rectangle',4,2))),
 E('Trace un carré de 2 carreaux de côté.','Quatre côtés de 2 carreaux, suivant les lignes du quadrillage.',('gridblank',None)),
 E('Complète les deux côtés déjà tracés pour former un rectangle.','Ajouter le côté droit de 2 carreaux et le côté du bas de 4 carreaux.',('partial',('rectangle',4,2))),
 E('Complète ce côté pour former un carré de 3 carreaux de côté.','Ajouter les trois autres côtés de 3 carreaux chacun.',('partial',('square',3,3))),
 E('Reproduis le triangle en reliant les mêmes croisements du quadrillage.','Même déplacement entre les sommets : 4 carreaux vers la droite, puis 3 vers le haut.',('copygrid',('triangle',4,3))),
 E('Dessine un rectangle de 5 carreaux sur 2 carreaux.','Deux côtés de 5 et deux côtés de 2 carreaux.',('gridblank',None)),
 E('Trace un carré de 4 carreaux de côté. Ajoute un trait pour obtenir deux rectangles identiques.','Tracer la ligne verticale ou horizontale du milieu, à 2 carreaux du bord.',('gridblank',None)),
 E('Deux triangles identiques peuvent-ils former un rectangle ? Fais un essai avec le matériel découpé.','Oui, avec deux triangles obtenus en coupant un rectangle suivant une diagonale.'),
 E('Lina compte 4 lignes de quadrillage pour un côté de 4 carreaux. Que doit-elle vérifier ?','Entre 4 lignes, il n’y a que 3 intervalles. Un côté de 4 carreaux relie 5 lignes successives.')],
 'Marquer les sommets avant de les relier ; réduire le modèle si nécessaire.', 'Le quadrillage sert de repère ; les longueurs en carreaux ne sont pas forcément des centimètres.')

C('Découvrir les solides','Géométrie','P3',
 'Je reconnais des solides et je décris leurs faces.','Balle, dé, boîte, cylindre, cône ; pâte adhésive et faces cartonnées.',
 'Manipule un dé et une boîte. Compte leurs faces en collant un petit repère sur chaque face déjà comptée.',
 ['Un cube a 6 faces carrées.', 'Un pavé droit a 6 faces rectangulaires ; certaines peuvent être carrées.', 'Je reconnais aussi une boule, un cylindre et un cône.'],
 'Le dé a la forme d’un cube. La boîte à chaussures a la forme d’un pavé droit.',('solids',None),
 'Quel solide ressemble à une balle ? À une boîte de conserve ?', 'La balle : une boule. La boîte de conserve : un cylindre.',[
 E('Nomme les solides A, B et C. Reconnais D et E.','A : cube ; B : pavé droit ; C : boule ; D : cylindre ; E : cône.',('solids',None)),
 E('Combien de faces a un cube ? Quelle est leur forme ?','6 faces carrées.'),
 E('Manipule une boîte en forme de pavé droit. Compte toutes ses faces.','6 faces. Certaines sont cachées quand on regarde la boîte.'),
 E('Une balle de tennis ressemble-t-elle à un disque ou à une boule ?','À une boule : c’est un objet en volume.'),
 E('Trouve dans la classe un objet en forme de cube et un autre en forme de pavé.','Exemples : dé ; boîte rectangulaire. Vérifier les objets choisis.'),
 E('Avec l’adulte, assemble 6 carrés cartonnés identiques pour former les faces d’un cube.','Six faces jointives ferment le cube. Un modèle réel aide à placer les faces.'),
 E('Construis une tour : deux cubes en bas côte à côte, puis un cube sur celui de gauche. Combien de cubes ?','3 cubes. Reproduire aussi la position de chacun.',('assembly',None)),
 E('Une image montre seulement 3 faces d’un cube. Le cube a-t-il seulement 3 faces ?','Non. Il a 6 faces en tout ; certaines sont cachées.'),
 E('Construis un pavé à partir de deux grands rectangles, deux moyens et deux petits, préparés par l’adulte.','Les faces opposées doivent se correspondre et les bords se rejoindre sans trou.')],
 'Utiliser des objets réels avant les dessins en perspective ; marquer les faces comptées.', 'Le dessin ne montre pas toutes les faces. Les tracés de patrons ne sont pas un prérequis.')

C('Se repérer et se déplacer','Espace','Dès P1, puis P3',
 'Je décris une position et je suis des instructions.','Objets de classe, un pion orienté et un plan simple.',
 'Cache un objet dans la classe. Donne un indice avec « sous », « sur », « entre » ou « à gauche de ». Puis fais un petit trajet.',
 ['Je précise par rapport à quoi je situe l’objet.', 'Sur le plan, je repère la porte, les tables et le tableau.', 'Avancer dépend du sens dans lequel le personnage regarde.'],
 'Le pion regarde vers le haut. Il avance de deux cases, tourne à droite, puis avance d’une case.',('route',None),
 'Mets un crayon à droite de ton cahier, puis sous le cahier.', 'Vérifier les positions avec l’enfant et le repère choisi.',[
 E('Sur le dessin, quel objet est entre A et C ?','B est entre A et C.',('sequence','ABC')),
 E('Place une gomme sur un cahier et un crayon sous ce cahier.','Vérifier la position réelle : gomme au-dessus, crayon en dessous.'),
 E('Sur une feuille, dessine un rond à gauche d’un carré.','Le rond est à gauche du carré pour le lecteur qui regarde la feuille.'),
 E('Le pion regarde vers le haut. Il avance de 2 cases puis tourne à droite et avance de 1 case. Trace le trajet.','Depuis le départ : deux cases vers le haut, puis une vers la droite.',('routeblank',None)),
 E('Le pion regarde vers la droite. Il tourne à gauche. Vers où regarde-t-il ?','Vers le haut de la feuille.'),
 E('Le pion regarde vers le haut. Il recule de 1 case. Vers où se déplace-t-il ?','Vers le bas, tout en restant orienté vers le haut.'),
 E('Avec l’adulte, dessine le plan de ta classe : porte, tableau et deux tables. Cache un objet et marque sa place.','Le plan doit permettre à un camarade de retrouver l’objet réel.'),
 E('Code un trajet entre deux tables de la classe. Utilise au plus 6 instructions et 2 virages.','Exemple à adapter : avance de 2 pas ; tourne à droite ; avance de 1 pas. Faire vérifier le trajet.'),
 E('Le pion regarde vers le haut : avance de 1, tourne à droite, avance de 2, tourne à droite, avance de 1. Où finit-il par rapport au départ ?','Deux cases à droite du départ, sur la même ligne. Il regarde vers le bas.',None,'(0+2,0+1-1)==(2,0)')],
 'Faire jouer les consignes avec le corps avant de déplacer un pion sur un plan.', 'Distinguer tourner sur place, avancer et reculer ; préciser l’orientation initiale.')

C('Enquêter, ranger, représenter','Données','P4',
 'Je recueille des réponses et je les organise.','Une feuille, des cubes et des crayons.',
 'Demande à 6 personnes de choisir chat ou chien. Note une marque par réponse. Assemble un cube par vote.',
 ['Je pose la même question à chaque personne.', 'Je note chaque réponse une seule fois.', 'Dans mon graphique, un carreau représente une personne.'],
 'Exemple : chat reçoit 4 votes et chien 2 votes. Les barres représentent 4 et 2 personnes.',('bars',[4,2]),
 'Si tu as 3 votes pour chat et 3 pour chien, quelle barre est la plus haute ?', 'Elles ont la même hauteur : il y a autant de votes.',[
 E('Enquête auprès de 6 à 12 personnes : « Préfères-tu chat ou chien ? » Note une marque par réponse.','Réponses réelles variables. Le nombre de marques doit égaler le nombre de personnes interrogées.'),
 E('Compte tes marques et complète le tableau avec les résultats de ton enquête.','Chaque ligne contient le nombre de votes pour l’animal indiqué ; le total doit correspondre aux personnes interrogées.',('surveytable',None)),
 E('Colorie une case par vote dans chaque colonne pour représenter tes résultats.','Les hauteurs des barres doivent reproduire exactement les deux effectifs du tableau.',('barblank',None)),
 E('Avec tes propres résultats, dis quel animal a le plus de votes, ou s’il y a égalité.','Comparer les deux effectifs de l’enquête réalisée ; accepter l’égalité.'),
 E('Dans le tableau, dessine les formes indiquées par la ligne et la colonne.','Ligne rond : un rond bleu et un rond hachuré. Ligne carré : un carré bleu et un carré hachuré.',('doubletable',None)),
 E('Dans ton enquête, une personne répond deux fois. Que faut-il faire ?','Ne garder qu’un seul choix pour cette personne ; une personne compte pour un vote.'),
 E('Prépare une enquête avec trois choix de jeux et interroge moins de 20 personnes.','Écrire les trois choix, recueillir une seule réponse par personne et compter chaque catégorie.'),
 E('Construis trois tours de cubes pour montrer les résultats de cette nouvelle enquête.','Une tour par choix, un cube par vote. Vérifier que le total des cubes égale le nombre de participants.'),
 E('Transforme les trois tours de cubes en un graphique sur ton cahier. Choisis un titre.','Trois barres nommées ; un carreau par personne ; titre lié à la question posée.')],
 'Recueillir réellement les données avant de remplir le tableau et de construire le graphique.', 'Ne pas réduire le CP à lire un graphique fourni. Vérifier le sens de chaque case du tableau.')

C('Poser une addition','Calcul','P4 ou P5',
 'J’aligne les unités et les dizaines.','Matériel de numération et papier quadrillé.',
 'Calcule 28 + 35 avec les barres et les cubes. Échange 10 unités contre une dizaine. Relie cet échange à la retenue.',
 ['J’écris les unités sous les unités et les dizaines sous les dizaines.', 'Je commence par les unités.', '10 unités font 1 dizaine : je note cette dizaine comme une retenue.'],
 '28 + 35 : 8 + 5 = 13. J’écris 3 unités et je retiens 1 dizaine. 2 + 3 + 1 = 6 dizaines. Résultat : 63.',('column',[28,35]),
 'Pose et calcule 24 + 13. Vérifie mentalement.', 'Unités : 4 + 3 = 7. Dizaines : 2 + 1 = 3. Résultat : 37.',[
 E('Pose et calcule 32 + 24.','6 unités et 5 dizaines : 56.',('columnblank',2),'32+24==56'),
 E('Pose et calcule 45 + 7.','5 + 7 = 12 : 2 unités, retenue 1 dizaine. Résultat : 52.',('columnblank',2),'45+7==52'),
 E('Pose et calcule 26 + 38.','6 + 8 = 14 : 4 unités, retenue 1. 2 + 3 + 1 = 6 dizaines. Résultat : 64.',None,'26+38==64'),
 E('Pose et calcule 47 + 29.','7 + 9 = 16. Puis 4 + 2 + 1 = 7 dizaines. Résultat : 76.',None,'47+29==76'),
 E('Pose et calcule 18 + 6 + 24.','8 + 6 + 4 = 18 : 8 unités, retenue 1. 1 + 2 + 1 = 4 dizaines. Résultat : 48.',('columnblank',3),'18+6+24==48'),
 E('Pose et calcule 59 + 41. Que se passe-t-il ?','9 + 1 = 10 : 0 unité et 1 dizaine. 5 + 4 + 1 = 10 dizaines, soit 100.',None,'59+41==100'),
 E('La classe a 36 cahiers et en reçoit 27. Combien en a-t-elle ? Pose l’addition puis réponds.','36 + 27 = 63. La classe a 63 cahiers.',None,'36+27==63'),
 E('Pour une sortie, 28 enfants et 16 adultes sont inscrits. Combien de personnes ?','28 + 16 = 44 personnes.',None,'28+16==44'),
 E('Lina pose 34 + 5 en plaçant le 5 sous le 3. Explique et corrige.','Le 5 représente des unités : il doit être sous le 4. 34 + 5 = 39.')],
 'Relier chaque écriture en colonne à un échange visible avec le matériel.', 'Introduire en P4 ou P5, après le calcul mental ; vérifier les unités, la retenue et le résultat.')
